<script>
  // ── Lucide icons
  lucide.createIcons();

  // ── Mobile menu
  const hamburger = document.getElementById('hamburger');
  const mobileMenu = document.getElementById('mobileMenu');
  const mobileMenuClose = document.getElementById('mobileMenuClose');

  hamburger.addEventListener('click', () => {
    mobileMenu.classList.add('open');
    hamburger.setAttribute('aria-expanded', 'true');
  });

  mobileMenuClose.addEventListener('click', () => {
    mobileMenu.classList.remove('open');
    hamburger.setAttribute('aria-expanded', 'false');
  });

  mobileMenu.addEventListener('click', (e) => {
    if (e.target === mobileMenu) {
      mobileMenu.classList.remove('open');
      hamburger.setAttribute('aria-expanded', 'false');
    }
  });

  // ── Carousel
  const track = document.getElementById('carouselTrack');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');
  const dots = document.querySelectorAll('.carousel-dot');

  let currentIndex = 0;
  const cards = track.querySelectorAll('.product-card');

  function getVisibleCount() {
    const w = window.innerWidth;
    if (w < 480) return 1;
    if (w < 768) return 2;
    if (w < 1024) return 3;
    return 4;
  }

  function getMaxIndex() {
    return Math.max(0, cards.length - getVisibleCount());
  }

  function updateCarousel() {
    const visible = getVisibleCount();
    const gap = 20;
    const containerWidth = track.parentElement.offsetWidth;
    const cardWidth = (containerWidth - gap * (visible - 1)) / visible;

    track.style.transform = `translateX(-${currentIndex * (cardWidth + gap)}px)`;

    prevBtn.disabled = currentIndex === 0;
    nextBtn.disabled = currentIndex >= getMaxIndex();

    // Update dots
    const dotIndex = Math.round(currentIndex / Math.ceil(cards.length / 2));
    dots.forEach((d, i) => {
      d.classList.toggle('active', i === Math.min(dotIndex, dots.length - 1));
      d.setAttribute('aria-selected', i === Math.min(dotIndex, dots.length - 1) ? 'true' : 'false');
    });
  }

  prevBtn.addEventListener('click', () => {
    if (currentIndex > 0) { currentIndex--; updateCarousel(); }
  });

  nextBtn.addEventListener('click', () => {
    if (currentIndex < getMaxIndex()) { currentIndex++; updateCarousel(); }
  });

  dots.forEach((dot, i) => {
    dot.addEventListener('click', () => {
      currentIndex = i === 0 ? 0 : Math.ceil(getMaxIndex() / (dots.length - 1)) * i;
      currentIndex = Math.min(currentIndex, getMaxIndex());
      updateCarousel();
    });
  });

  window.addEventListener('resize', () => {
    currentIndex = Math.min(currentIndex, getMaxIndex());
    updateCarousel();
  });

  updateCarousel();

  // ── Store locator
  const locatorForm = document.getElementById('locatorForm');
  const storeResults = document.getElementById('storeResults');

  locatorForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const zip = document.getElementById('zipInput').value.trim();
    if (!zip) return;

    storeResults.classList.remove('visible');
    setTimeout(() => {
      storeResults.classList.add('visible');
      lucide.createIcons();
    }, 300);
  });

  // ── Newsletter
  const newsletterForm = document.getElementById('newsletterForm');
  const newsletterConfirm = document.getElementById('newsletterConfirm');

  newsletterForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = document.getElementById('emailInput').value.trim();
    if (!email || !email.includes('@')) return;

    newsletterForm.style.display = 'none';
    newsletterConfirm.classList.add('visible');
  });

  // ── Category keyboard support
  document.querySelectorAll('.category-card').forEach(card => {
    card.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        card.click();
      }
    });
  });

  // ── Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', (e) => {
      const target = document.querySelector(anchor.getAttribute('href'));
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        if (mobileMenu.classList.contains('open')) {
          mobileMenu.classList.remove('open');
          hamburger.setAttribute('aria-expanded', 'false');
        }
      }
    });
  });
</script>

